"""Generate native comparisons, retaining explicit upstream expectations."""
import json
from pathlib import Path
root = Path(__file__).resolve().parents[2]
fixtures = json.loads((root / 'scripts/paperjs/curves.json').read_text())['fixtures']
def num(n):
    s=repr(float(n))
    return s
out=['''// Adapted from pinned Paper.js Curve.js; MIT, copyright 2011–2020
// Jürg Lehni & Jonathan Puckey. See scripts/paperjs/upstream/LICENSE.txt.
// Generated by scripts/paperjs/generate-curves.py.
import gleam/float
import gleeunit/should
import svg_path
import svg_path/curvature
import svg_path/measure

fn near(actual: Float, expected: Float, tolerance: Float) {
  assert float.absolute_value(actual -. expected) <=. tolerance
}
''']
for f in fixtures:
    c=f['curve'];t=num(f['args'][0]);method=f['method'];id=f['id']
    out.append(f'// Upstream block {f["block"]}: {f["title"]}\npub fn paper_curve_{id}_test() {{')
    out.append('  let curve = svg_path.CubicBezier('+','.join(f'svg_path.Point({num(c[i])}, {num(c[i+1])})' for i in [0,2,4,6])+')')
    tol='0.00000001';expected=f['expected']
    if method=='getPointAtTime':
        out.append(f'  let assert Ok(p) = svg_path.segment_point(curve, at: {t})')
        if f['component']:
            out.append(f'  p.y |> should.equal({num(expected)})')
        else:
            for field,e in zip(['x','y'],expected):out.append(f'  near(p.{field}, {num(e)}, 0.00001)')
    elif 'Tangent' in method or 'Normal' in method:
        out.append(f'  let assert Ok(d) = svg_path.segment_derivative(curve, at: {t})')
        if 'Weighted' not in method:
            out.append('  let assert Ok(n) = float.square_root(d.x *. d.x +. d.y *. d.y)')
            out.append('  let d = svg_path.Point(d.x /. n, d.y /. n)')
            tol='0.0000001'
        else:tol='0.00001'
        fields=['d.y','0.0 -. d.x'] if 'Normal' in method else ['d.x','d.y']
        for v,e in zip(fields,expected):out.append(f'  near({v}, {num(e)}, {tol})')
    elif method=='getCurvatureAtTime':
        if id in [32,36]:
            out.append('// Paper returns zero; our documented zero-speed curvature is undefined.')
            out.append(f'  curvature.segment_left_normal_curvature(curve, at: {t})\n    |> should.equal(Error(curvature.DegenerateCurvatureDerivative))')
        else:
            out.append(f'  let assert Ok(k) = curvature.segment_left_normal_curvature(curve, at: {t})')
            out.append(f'  near(0.0 -. k, {num(expected)}, 0.000000000001)')
    elif method=='getTimeAt':
        out.append(f'  let assert Ok(t) = measure.segment_parameter_at_length(curve, distance: {t})')
        if id==38:
            out.append('// Paper snaps to 1; validate our returned parameter in distance units.')
            out.append('  assert t >=. 0.0 && t <=. 1.0')
            out.append('  let distance = { 1584.4999999999998 -. 1520.5 } *. t *. t *. { 3.0 -. 2.0 *. t }')
            out.append(f'  near(distance, {num(f["args"][0])}, measure.default_length_options().tolerance)')
        else:out.append(f'  near(t, {num(expected)}, {tol})')
    elif method=='getPartLength':
        out.append(f'  let assert Ok(part) = svg_path.segment_between(curve, from: {t}, to: {num(f["args"][1])})')
        out.append('  let assert Ok(length) = measure.segment_length(part)')
        out.append(f'  near(length, {num(expected)}, {tol})')
    out.append('}\n')
(root/'test/svg_path_paper_curves_test.gleam').write_text('\n'.join(out))
